drills.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  01 · detect changes★★☆ core
//  concepts: snapshots · Equals · key properties
// ─────────────────────────────────────────────────────────────────────────
//
//  Compare the snapshot with the current values, exactly like DetectChanges.

using static Bootcamp.Check;

IReadOnlyList<string> ModifiedProperties(IReadOnlyDictionary<string, object?> original, IReadOnlyDictionary<string, object?> current, string keyProperty)
{
    var changed = new List<string>();
    foreach (var (name, before) in original)
    {
        if (Equals(before, current[name])) continue;
        if (name == keyProperty) throw new InvalidOperationException($"The property '{name}' is part of a key and cannot be modified.");
        changed.Add(name);
    }
    return changed;
}

Dictionary<string, object?> Row(params (string Name, object? Value)[] cols)
{
    var d = new Dictionary<string, object?>();
    foreach (var (n, v) in cols) d[n] = v;
    return d;
}

drills.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("only the changed column is reported", () =>
    Eq(ModifiedProperties(Row(("Id", 1), ("Name", "Ana"), ("Total", 10.0m)), Row(("Id", 1), ("Name", "Ana L."), ("Total", 10.00m)), "Id"), new[] { "Name" }));

Test("null versus a value is a change, both ways", () =>
    Eq(ModifiedProperties(Row(("Id", 1), ("Bio", null), ("Phone", "123")), Row(("Id", 1), ("Bio", "hi"), ("Phone", null)), "Id"), new[] { "Bio", "Phone" }));

Test("results follow the snapshot's property order", () =>
    Eq(ModifiedProperties(Row(("Id", 7), ("A", 1), ("B", 2), ("C", 3)), Row(("Id", 7), ("C", 30), ("B", 2), ("A", 10)), "Id"), new[] { "A", "C" }));

Test("changing the key throws", () =>
    Throws<InvalidOperationException>(() => ModifiedProperties(Row(("Id", 1), ("Name", "a")), Row(("Id", 2), ("Name", "a")), "Id")));

Test("an unchanged entity has no modified properties (boundary)", () =>
    Eq(ModifiedProperties(Row(("Id", 1), ("Name", "a"), ("When", new DateTime(2026, 1, 1))), Row(("Id", 1), ("Name", "a"), ("When", new DateTime(2026, 1, 1))), "Id").Count, 0));

drills.explanation:
Walk the snapshot in order and compare each value with `object.Equals`, which unboxes and uses each type's own equality (decimal ignores trailing zeros; two nulls are equal):

```csharp
foreach (var (name, before) in original)
{
    if (Equals(before, current[name])) continue;
    if (name == keyProperty) throw new InvalidOperationException(...);
    changed.Add(name);
}
```

Comparing with `==` on the `object?` values would compare references of the boxed values and report every value-type column as modified.
